import{_ as t,o as a,c as l,a5 as o}from"./chunks/framework.DrDMl0tG.js";const b=JSON.parse('{"title":"Server Example: Tablecloth Pull","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/tablecloth_pull.md","filePath":"sections/examples/server/tablecloth_pull.md"}'),s={name:"sections/examples/server/tablecloth_pull.md"};function i(r,e,h,n,c,d){return a(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="server-example-tablecloth-pull" tabindex="-1">Server Example: Tablecloth Pull <a class="header-anchor" href="#server-example-tablecloth-pull" aria-label="Permalink to &quot;Server Example: Tablecloth Pull&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The tablecloth trick: three dishes stand on a cloth on a table, and a sharp pull on the cloth&#39;s edge whips it out from under them. Kinetic friction (0.3) acts on the dishes only for the fraction of a second the cloth slides under them, too briefly to take them along: they shift by about 3 cm and stay on the table. The cloth is solved together with the dishes and the table (<a href="./../../DeformableObject.html#solving-deformables-together-with-the-bodies"><code>World::setMonolithicDeformables()</code></a>). Every three seconds the world starts over, and the example prints how far the dishes moved.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>tablecloth_pull</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/tablecloth_pull</span></span></code></pre></div><p>Connect <code>rayrai_tcp_viewer</code> to port 8080. On Windows, run <code>build-examples/bin/tablecloth_pull.exe</code>.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>The cloth is 0.8 m by 0.64 m, 41 x 33 particles weighing 0.2 kg in total, with nearly inextensible edges and a little air drag.</li><li>The dishes are 0.6 kg cylinders, 0.14 m across. The friction coefficient is 0.3 between the cloth and both the table and the dishes, and 0.5 between the dishes and the table.</li><li>One second into each cycle, a 60 N force pulls the cloth&#39;s edge outward and slightly down for 0.15 s.</li><li>The scene lives in <code>include/tablecloth_pull.hpp</code>.</li></ul>',10)])])}const u=t(s,[["render",i]]);export{b as __pageData,u as default};
